-- Removes the now-irrelevant spell_mage_magic_absorption binding (negative spell_id = binds to
-- every rank of the talent whose first rank is spell 29441) - it implements a real stock mechanic
-- ("restore mana when a spell is fully resisted") that isn't part of this rework's redesigned (1,0)
-- at all, and was only still bound because the base row was never cleaned up when this talent's
-- content was fully replaced in the Rows 0-3 batch. Leaving it bound produced the harmless-but-
-- confusing boot-log warning that led to finding this whole gap; removing it for real rather than
-- just working around the symptom.
DELETE FROM `spell_script_names` WHERE `spell_id` = -29441 AND `ScriptName` = 'spell_mage_magic_absorption';
